INSERT INTO tickets (id, type, parent_id, title, description, status, priority, assigned_to, team, decision_ref, created_at, updated_at, deleted_at, hash, canonical_version) VALUES ('T-45', 'task', NULL, 'implement or formally defer documented DSL grammar surface', 'docs/pql-grammar.md documents operators/functions that are not implemented, so documented examples error at runtime (surfaced by the 2026-05-31 docs-vs-code audit): (1) REGEXP — parser emits it but no UDF is registered (only ''reverse'' in internal/store/udf.go), so ''name REGEXP ...'' fails with ''no such function'' (exit 70); (2) functions contains/position/slice/dirname/basename/extension/now()/today() and cast(x AS type) are absent from functionMap (internal/query/dsl/eval/compile.go) and CAST has no parse rule; (3) array columns inside length()/array fns error with bare_array_ref. Either implement these (register REGEXP UDF, add the functions + a CAST parse rule, allow array fns in projections) or keep them deferred. Interim: docs/pql-grammar.md has been marked ''planned'' for the unimplemented parts; this ticket tracks closing the gap for real.', 'ready', 'medium', NULL, NULL, NULL, '2026-05-31 12:25:23', '2026-06-08 14:39:01', NULL, '41b4815faf1fac43af2e121e1485d148', 1) ON CONFLICT(id) DO UPDATE SET type=excluded.type, parent_id=excluded.parent_id, title=excluded.title, description=excluded.description, status=excluded.status, priority=excluded.priority, assigned_to=excluded.assigned_to, team=excluded.team, decision_ref=excluded.decision_ref, updated_at=excluded.updated_at, deleted_at=excluded.deleted_at, hash=excluded.hash, canonical_version=excluded.canonical_version WHERE excluded.updated_at > tickets.updated_at OR (excluded.updated_at = tickets.updated_at AND excluded.hash > tickets.hash);
